mapper.update:
update kitchen_printers
set is_primary = 0
where kitchen_station_id = #{stationId,jdbcType=INTEGER}
  and deleted_at is null
  and is_primary = 1

    and id <> #{exceptId,jdbcType=INTEGER}

mapper.select:
select 
from kitchen_printers p
where p.kitchen_station_id = #{stationId,jdbcType=INTEGER}
  and p.name = #{name,jdbcType=VARCHAR}
  and p.deleted_at is null
limit 1
